"""Dependency-free local recording/SOP library. All document text is escaped."""
SOP_PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>录像与 SOP</title>
<style>
:root{color-scheme:light dark;--bg:light-dark(#f5f7fa,#111925);--paper:light-dark(#fff,#1a2637);--text:light-dark(#243044,#e4eaf3);--muted:light-dark(#64748b,#a7b6ca);--line:light-dark(#e1e7ef,#34455d);--soft:light-dark(#edf3fb,#243955);--blue:light-dark(#215da8,#9bc1ff);--primary:#255fae;--ok:light-dark(#236144,#b6d9c4);--warn:light-dark(#87511b,#efc499);--warnbg:light-dark(#fff4e5,#3b2d20)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.55 system-ui,'Microsoft YaHei',sans-serif}button,input,select,textarea{font:inherit;color:inherit}button,a,summary{cursor:pointer}button{border:1px solid var(--line);background:var(--paper);border-radius:6px;padding:7px 12px}button:disabled{opacity:.45;cursor:default}a{color:var(--blue)}:focus-visible{outline:2px solid var(--blue);outline-offset:3px}[hidden]{display:none!important}.primary{background:var(--primary);color:#fff;border-color:transparent}.link{background:transparent;border:0;padding:3px 0;color:var(--blue);text-decoration:none}.muted,.meta{color:var(--muted)}.meta{font-size:12px}.shell{max-width:1440px;min-height:100dvh;margin:auto;background:var(--paper)}header{padding:22px 30px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}header h1{margin:8px 0 0;font-size:22px;font-weight:600}h1 small{font-size:12px;font-weight:400;color:var(--muted);margin-left:10px}.back{font-size:12px;text-decoration:none;color:var(--muted)}.body{padding:0 30px 28px}.tabs{display:flex;gap:26px;border-bottom:1px solid var(--line)}.tabs button{border:0;border-radius:0;padding:17px 0 12px;background:none;color:var(--muted);border-bottom:2px solid transparent}.tabs button[aria-selected=true]{color:var(--blue);border-color:var(--blue)}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 12px}input,select,textarea{background:var(--paper);border:1px solid var(--line);border-radius:6px;padding:8px 10px;min-width:0}.filters input{width:min(330px,100%)}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;min-width:670px;font-size:13px}th{font-size:12px;font-weight:400;color:var(--muted);padding:12px 8px;border-bottom:1px solid var(--line)}td{padding:18px 8px;vertical-align:middle;border-bottom:1px solid var(--line)}th:first-child,td:first-child{padding-left:0}td:last-child,th:last-child{text-align:right;padding-right:0}.sub{display:block;font-size:11px;color:var(--muted);margin-top:4px}.status{display:inline-block;padding:2px 7px;border-radius:4px;background:var(--soft);color:var(--blue);font-size:12px;white-space:nowrap}.status.published{color:var(--ok)}.status.error{background:var(--warnbg);color:var(--warn)}.actions{display:flex;justify-content:flex-end;align-items:center;gap:12px;white-space:nowrap}.actions button{font-size:12px}.empty{padding:32px;text-align:center;color:var(--muted)}.foot{font-size:12px;color:var(--muted);margin-top:16px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}details>summary{font-size:12px;color:var(--muted)}dialog{max-width:calc(100vw - 24px);width:430px;max-height:calc(100dvh - 30px);overflow:auto;border:1px solid var(--line);border-radius:12px;padding:22px;background:var(--paper);color:var(--text);box-shadow:0 20px 60px #0003}dialog::backdrop{background:#0005}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.dialog-head h2{font-size:19px;margin:0}.x{border:0;background:none;color:var(--muted);font-size:22px;padding:0 3px}.field{display:grid;gap:7px;margin-top:16px;font-size:12px;color:var(--muted)}.field input,.field select,.field textarea{width:100%;font-size:14px}.dialog-foot{display:flex;justify-content:flex-end;gap:9px;flex-wrap:wrap;margin-top:24px}.optional{margin-top:18px}.optional .field{margin-top:12px}#playerDialog{width:960px}video{display:block;width:100%;background:#111827;border-radius:6px;margin-top:14px;max-height:70dvh}#notice{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);padding:10px 16px;max-width:calc(100vw - 24px);background:var(--paper);border:1px solid var(--line);border-radius:8px;box-shadow:0 5px 25px #0002;z-index:30;font-size:13px}.compare{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr)}.video-pane{padding:24px;background:var(--bg);border-right:1px solid var(--line);min-width:0}.sop-pane{padding:24px;min-width:0}.pane-title{display:flex;justify-content:space-between;gap:10px;font-size:12px;color:var(--muted);margin-bottom:12px}.compare video{margin-top:0;max-height:500px}.steps{padding:0;list-style:none;counter-reset:step}.steps li{counter-increment:step;padding:13px 12px;margin:5px 0;border-radius:6px}.steps li.active{background:var(--soft)}.step-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.step-head strong{font-size:13px;font-weight:600}.steps p{font-size:13px;margin:8px 0}.steps .meta{font-size:12px}.timestamp{font-size:12px;white-space:nowrap}.pending{padding:13px;background:var(--warnbg);border-radius:7px;color:var(--warn);margin-top:20px}.pending summary{color:var(--warn)}.pending .field{color:var(--warn)}.doc{font-size:13px;overflow-wrap:anywhere}.doc h1,.doc h2,.doc h3{font-size:16px;margin:20px 0 8px}.doc p{margin:8px 0}.doc table{min-width:600px;font-size:12px}.doc td,.doc th{padding:8px;text-align:left}.doc li{margin:5px 0}.doc pre,#diffText{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.editor{width:100%;min-height:360px;font:12px/1.6 ui-monospace,monospace;margin-top:12px}#reviewHeadActions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.source-info{margin-top:20px}.source-info dl>div{display:grid;grid-template-columns:80px minmax(0,1fr);gap:10px;margin:10px 0;font-size:12px}.source-info dt{color:var(--muted)}.source-info dd{margin:0;overflow-wrap:anywhere}.review-footer{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:16px;font-size:12px}.task-controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.danger{color:var(--warn)}#connection{font-size:12px;color:var(--muted)}@media(max-width:750px){.compare{grid-template-columns:1fr}.video-pane{border:0;border-bottom:1px solid var(--line)}header{padding:18px}.body{padding:0 18px 22px}.video-pane,.sop-pane{padding:18px}.filters input{flex:1;width:auto}dialog{padding:18px}h1 small{display:block;margin-left:0;margin-top:3px}}@media(pointer:coarse){button,summary{min-height:44px}input,select,textarea{font-size:16px!important}}
</style></head><body>
<div class="shell">
<section id="listView"><header><div><a class="back" href="/">← 返回实时画面</a><h1>录像与 SOP <small id="target"></small></h1></div><span id="connection" role="status">连接中…</span></header><div class="body">
<div class="tabs" role="tablist" aria-label="资料类型"><button id="videoTab" role="tab" aria-controls="videoPanel" aria-selected="true">录像</button><button id="sopTab" role="tab" aria-controls="sopPanel" aria-selected="false">SOP</button></div>
<div class="filters"><input id="search" type="search" aria-label="搜索作业、日期或环境" placeholder="搜索作业、日期、环境…"><select id="filter" aria-label="整理状态"><option value="all">全部状态</option><option value="pending">待选择</option><option value="later">待整理</option><option value="running">整理中</option><option value="review">待核对</option><option value="published">可用</option><option value="error">需处理</option><option value="keep">仅保留录像</option></select></div>
<div id="videoPanel" role="tabpanel" aria-labelledby="videoTab"><div class="table-scroll"><table><thead><tr><th>作业日期 JST</th><th>作业</th><th>整理状态</th><th>SOP</th><th>操作</th></tr></thead><tbody id="recordRows"></tbody></table></div><div id="videoEmpty" class="empty" hidden>没有匹配的录像</div></div>
<div id="sopPanel" role="tabpanel" aria-labelledby="sopTab" hidden><div class="table-scroll"><table><thead><tr><th>SOP</th><th>版本</th><th>状态</th><th>更新日期 JST</th><th>操作</th></tr></thead><tbody id="sopRows"></tbody></table></div><div id="sopEmpty" class="empty" hidden>尚无已发布 SOP</div></div>
<div class="foot"><span>日期可修正 · 文件名与分析记录收在详情中</span><span><button class="link" id="refresh">刷新</button> · <button class="link" id="backup">备份台账</button></span></div>
</div></section>
<section id="reviewView" hidden><header><div><button class="back link" id="backList">← 录像与 SOP</button><h1 id="reviewTitle"></h1><div class="meta" id="reviewMeta"></div></div><div id="reviewHeadActions"><button id="usageFeedback" hidden>使用反馈</button><button id="createRevision" hidden>创建修订草稿</button><button id="editDraft">编辑 SOP</button><button id="saveDraft">保存草稿</button><button class="primary" id="publish">核对通过并发布</button></div></header>
<div class="compare"><div class="video-pane"><div class="pane-title"><span>来源录像</span><span id="sourceDate"></span></div><video id="reviewVideo" controls preload="metadata"></video><div id="missingMedia" class="pending" hidden>录像文件缺失；SOP 和历史引用仍保留。</div><div class="source-info"><details><summary>录像与版本信息</summary><dl id="sourceInfo"></dl><div class="task-controls"><button id="openOriginal">本机打开录像</button><button id="openSop">本机打开 SOP</button><button id="downloadSop">下载 SOP</button><button id="versionHistory">历史版本</button></div></details></div><details id="previousSection" class="source-info" hidden><summary>与已发布版本的差异</summary><pre id="diffText"></pre></details></div>
<article class="sop-pane"><div class="pane-title"><span>SOP</span><span id="versionLabel"></span></div><div id="goal" class="meta"></div><ol id="steps" class="steps"></ol><details><summary>完整 SOP 正文</summary><div id="markdown" class="doc"></div></details><textarea id="draftEditor" class="editor" aria-label="SOP 草稿正文" hidden></textarea><details id="pending" class="pending" open><summary id="pendingTitle">待确认</summary><label class="field">适用环境<input id="reviewEnvironment" maxlength="120" placeholder="核对后填写系统 / 环境 / Client"></label><div id="questions"></div><label class="field">核对人<input id="reviewer" maxlength="80" placeholder="姓名或本机标识"></label></details><div id="publishedInfo" class="meta" hidden></div><div class="review-footer"><span id="reviewHint" class="muted"></span></div></article></div></section>
</div>
<dialog id="generateDialog"><div class="dialog-head"><h2 id="generateTitle">生成 SOP</h2><button class="x" data-close="generateDialog" aria-label="关闭">×</button></div><p class="meta" id="generateHelp">Antigravity 后台整理，完成后再核对。</p><label class="field">作业名称<input id="taskName" maxlength="160" placeholder="例如：配置检查与保存"></label><label class="field">作业日期<input id="taskDate" type="date"></label><details class="optional"><summary>更多信息 · 选填</summary><label class="field">环境<input id="taskEnvironment" maxlength="120" placeholder="待确认"></label><label class="field" id="sopSelectField">整理方式<select id="sopSelect"><option value="">新建 SOP</option></select></label></details><div class="dialog-foot"><button data-close="generateDialog">返回</button><button class="primary" id="startAnalysis">开始整理</button></div></dialog>
<dialog id="playerDialog"><div class="dialog-head"><h2 id="playerTitle">录像</h2><button class="x" data-close="playerDialog" aria-label="关闭播放">×</button></div><video id="player" controls preload="metadata"></video></dialog>
<dialog id="infoDialog"><div class="dialog-head"><h2 id="infoTitle">详情</h2><button class="x" data-close="infoDialog" aria-label="关闭详情">×</button></div><div id="infoBody"></div></dialog>
<dialog id="feedbackDialog"><div class="dialog-head"><h2 id="feedbackTitle">使用反馈</h2><button class="x" data-close="feedbackDialog" aria-label="关闭使用反馈">×</button></div><p class="meta">记录本次版本、环境和作业范围；一次成功只代表本次结果。请勿填写密码。</p><label class="field">结果类型<select id="feedbackKind"><option value="issue">遇到问题</option><option value="suggestion">改进建议</option><option value="success">本次成功</option></select></label><label class="field">作业日期<input id="feedbackDate" type="date"></label><label class="field">本次环境<input id="feedbackEnvironment" maxlength="120"></label><label class="field">本次作业范围／工单<input id="feedbackScenario" maxlength="300" placeholder="例如：一个用户、某用户组、工单编号"></label><label class="field">结果、问题及核对依据<textarea id="feedbackNote" maxlength="3000" rows="4" placeholder="步骤、预期和实际结果、报错或证据位置；不要填写凭据"></textarea></label><div class="dialog-foot"><button data-close="feedbackDialog">返回</button><button id="saveFeedback" class="primary">保存反馈</button></div><details class="source-info"><summary>此 SOP 的历史反馈</summary><div id="feedbackLog"></div></details></dialog>
<dialog id="authDialog"><h2>连接资料库</h2><p class="meta">使用录屏服务的密码。</p><label class="field">密码<input id="password" type="password" autocomplete="current-password"></label><p id="authError" role="alert"></p><div class="dialog-foot"><button id="login" class="primary">连接</button></div></dialog>
<div id="notice" role="status" hidden></div>
<script>
'use strict';
const $=id=>document.getElementById(id), escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let socket,serial=0,pending=new Map(),snapshot={recordings:[],sops:[]},current=null,editing=null,detail=null,tab='video',ready=false,queryHandled=false;
const urlParams=new URLSearchParams(location.search);let noticeTimer;
function notify(message){$('notice').textContent=message;$('notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').hidden=true,5000);}
function request(action,args={}){return new Promise((resolve,reject)=>{if(!ready||socket.readyState!==WebSocket.OPEN)return reject(Error('尚未连接，请稍后重试'));const id=++serial;const timer=setTimeout(()=>{pending.delete(id);reject(Error('请求超时，请刷新确认状态，避免重复发布'));},60000);pending.set(id,{resolve,reject,timer});socket.send(JSON.stringify({action,request:id,...args}));});}
function connect(){socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/sop/ws');socket.onmessage=async e=>{try{const msg=JSON.parse(e.data);if(msg.type==='auth_required'){const token=sessionStorage.getItem('kvmToken')||localStorage.getItem('kvmToken');if(token)socket.send(JSON.stringify({type:'auth',token}));else $('authDialog').showModal();}else if(msg.type==='auth_ok'){sessionStorage.setItem('kvmToken',msg.token);$('authDialog').close();}else if(msg.type==='auth_failed'){$('authError').textContent=msg.error;if(!$('authDialog').open)$('authDialog').showModal();}else if(msg.type==='ready'){ready=true;$('connection').textContent='本机资料';await refresh();}else if(msg.type==='reply'){const promise=pending.get(msg.request);if(promise){clearTimeout(promise.timer);pending.delete(msg.request);msg.error?promise.reject(Error(msg.error)):promise.resolve(msg.result);}}}catch(error){notify(error.message);}};socket.onclose=()=>{ready=false;$('connection').textContent='连接中断 · 自动重连';for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('连接中断，请刷新确认操作结果'));}pending.clear();setTimeout(connect,2500);};socket.onerror=()=>{};}
$('login').onclick=()=>{socket.send(JSON.stringify({type:'auth',password:$('password').value}));$('password').value='';};
async function refresh(){snapshot=await request('snapshot');$('target').textContent=snapshot.target;renderLists();if(!queryHandled){queryHandled=true;const id=urlParams.get('generate')||urlParams.get('recording');const r=snapshot.recordings.find(x=>x.id===id);if(r&&urlParams.has('generate'))generate(r);else if(r&&urlParams.has('recording'))info(r);}}
const stamp=s=>s?new Date(s).toLocaleString('sv-SE',{timeZone:'Asia/Tokyo',hour12:false}):'未知';
function duration(r){const s=r.media.probed_duration??r.media.duration_seconds;return s?String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0'):'时长待探测';}
function recordStatus(r){if(r.media.missing)return ['error','文件缺失'];if(r.job){const m={queued:['running','排队中'],waiting_media:['running','等待 MP4'],running:['running','整理中'],review:['review','待核对'],published:['published','可用'],failed:['error','整理失败'],blocked:['error','需处理'],canceled:['later','已取消']};return m[r.job.status]||['error',r.job.status];}if(r.media.state.includes('failed'))return ['error','转码失败'];return [{later:'later',keep:'keep',pending:'pending'}[r.choice]||'pending',{later:'待整理',keep:'仅保留录像',pending:'待选择'}[r.choice]||'待整理'];}
function button(action,label,id,cls='link'){return `<button class="${cls}" data-action="${action}" data-id="${escapeText(id)}">${escapeText(label)}</button>`;}
function renderLists(){const q=$('search').value.trim().toLowerCase(),f=$('filter').value;let n=0;const rows=snapshot.recordings.filter(r=>{const state=recordStatus(r)[0];return (!q||[r.title,r.operation_date,r.environment,r.media.name].join(' ').toLowerCase().includes(q))&&(f==='all'||f===state);});$('recordRows').innerHTML=rows.map(r=>{n++;const [state,label]=recordStatus(r);const job=r.job;const latest=r.versions[0];const primary=job&&['review','published'].includes(job.status)?button('review','核对',r.id,'primary'):job&&['running','queued','waiting_media'].includes(job.status)?button('info','进度',r.id):job&&['failed','blocked','canceled'].includes(job.status)?button('retry','重试',r.id):button('generate','生成 SOP',r.id);return `<tr><td>${escapeText(r.operation_date||'日期未知')}<span class="sub">${escapeText(r.media.recorded_start_at?stamp(r.media.recorded_start_at).slice(11,16):'录制时间未知')} · ${escapeText(duration(r))}</span></td><td>${button('info',r.title,r.id)}<span class="sub">${escapeText(r.environment||'环境待确认')}</span></td><td><span class="status ${state}">${escapeText(label)}</span>${job&&job.status==='running'?`<span class="sub">${job.done} / ${job.total||'…'} 段</span>`:''}</td><td>${latest?button('version','v'+latest.number,latest.id):job&&job.status==='review'?button('review','草稿',r.id):'—'}</td><td><div class="actions">${r.url?button('play','播放',r.id):''}${primary}${button('info','⋯',r.id)}</div></td></tr>`;}).join('');$('videoEmpty').hidden=n>0;
const sops=snapshot.sops.filter(s=>(!q||[s.title,s.slug].join(' ').toLowerCase().includes(q))&&(f==='all'||f===(s.active?'published':'error')));$('sopRows').innerHTML=sops.map(s=>`<tr><td>${escapeText(s.title)}<span class="sub">${s.recordings} 份来源录像</span></td><td>v${s.number||'—'}</td><td><span class="status ${s.active?'published':'error'}">${s.active?'可用':'已停用'}</span><span class="sub">${s.successful_runs?'当前版使用成功 '+s.successful_runs+' 次（限记录范围）':'当前版待实机试用'}${s.open_feedback?' · '+s.open_feedback+' 项反馈待处理':''}</span></td><td>${escapeText(stamp(s.reviewed_at).slice(0,10))}</td><td>${button('version','查看',s.current_version)} ${s.active?button('withdraw','停用',s.id):''}</td></tr>`).join('');const documents=(snapshot.documents||[]).filter(d=>(!q||d.title.toLowerCase().includes(q))&&(f==='all'||f==='pending'));$('sopRows').innerHTML+=documents.map(d=>`<tr><td>${escapeText(d.title)}<span class="sub">已有 SOP 文档</span></td><td>—</td><td><span class="status">待登记核对</span></td><td>${escapeText(stamp(d.modified*1000).slice(0,10))}</td><td>${button('document','查看',d.id)}</td></tr>`).join('');const drafts=snapshot.recordings.filter(r=>r.job?.status==='review'&&(!q||r.title.toLowerCase().includes(q))&&(f==='all'||f==='review'));$('sopRows').innerHTML+=drafts.map(r=>`<tr><td>${escapeText(r.title)}<span class="sub">来源录像草稿</span></td><td>—</td><td><span class="status">待核对</span></td><td>${escapeText(stamp(r.job.updated_at).slice(0,10))}</td><td>${button('review','核对',r.id)}</td></tr>`).join('');$('sopEmpty').hidden=sops.length+documents.length+drafts.length>0;}
function selectTab(value){tab=value;$('videoTab').setAttribute('aria-selected',String(value==='video'));$('sopTab').setAttribute('aria-selected',String(value==='sop'));$('videoPanel').hidden=value!=='video';$('sopPanel').hidden=value!=='sop';}
$('videoTab').onclick=()=>selectTab('video');$('sopTab').onclick=()=>selectTab('sop');$('search').oninput=renderLists;$('filter').onchange=renderLists;$('refresh').onclick=()=>refresh().catch(e=>notify(e.message));
function generate(r,metadata=false){current=r;editing=metadata;$('generateTitle').textContent=metadata?'编辑作业资料':'生成 SOP';$('generateHelp').textContent=metadata?'作业日期可独立修正；录制时间保留来源。':'Antigravity 后台整理，完成后再核对。';$('startAnalysis').textContent=metadata?'保存':'开始整理';$('taskName').value=r.title==='未命名录像'?'':r.title;$('taskDate').value=r.operation_date||'';$('taskEnvironment').value=r.environment;$('sopSelectField').hidden=metadata;$('sopSelect').innerHTML='<option value="">新建 SOP</option>'+snapshot.sops.filter(s=>s.active).map(s=>`<option value="${escapeText(s.id)}">更新：${escapeText(s.title)} · v${s.number}</option>`).join('');$('generateDialog').showModal();}
$('startAnalysis').onclick=async()=>{const button=$('startAnalysis');button.disabled=true;try{if(!$('taskDate').value)throw Error('请确认业务作业日期');await request(editing?'edit':'enqueue',{id:current.id,title:$('taskName').value||'未命名作业',date:$('taskDate').value,environment:$('taskEnvironment').value,sop_id:$('sopSelect').value||null});$('generateDialog').close();notify(editing?'资料已保存':'已加入整理队列，可以继续工作');await refresh();}catch(e){notify(e.message);}finally{button.disabled=false;}};
function play(r){$('playerTitle').textContent=r.title;$('player').src=r.url;$('playerDialog').showModal();}
function info(r){current=r;const job=r.job;const source=r.media;let html=`<p class="meta">${escapeText(r.title)} · ${escapeText(recordStatus(r)[1])}</p><dl class="meta"><dt>业务作业日期</dt><dd>${escapeText(r.operation_date||'未知')}</dd><dt>录制开始 JST</dt><dd>${escapeText(stamp(source.recorded_start_at))} (${escapeText(source.date_source)})</dd><dt>录像文件</dt><dd style="overflow-wrap:anywhere">${escapeText(source.name)}</dd><dt>体积</dt><dd>${(source.size/1048576).toFixed(1)} MiB</dd></dl><div class="task-controls">${button('metadata','编辑资料',r.id)}${r.url?`<a class="link" href="${escapeText(r.url)}&download=1" download>下载录像</a>`:''}${button('open','本机打开',r.id)}${button('reveal','定位文件',r.id)}</div>`;
if(job){html+=`<details class="source-info"><summary>分析记录</summary><p class="meta">${escapeText(job.message)} · ${job.done}/${job.total} 段</p>${job.error?`<p class="danger">${escapeText(job.error)}</p>`:''}<p class="meta">分析材料与详细日志保存在 Host 的 .local/video-analysis/${escapeText(job.id)}/。</p></details><div class="task-controls">${['running','queued','waiting_media'].includes(job.status)?button('cancel','取消整理',r.id):['failed','blocked','canceled'].includes(job.status)?button('retry','重试整理',r.id):''}</div>`;}
if(source.path.endsWith('.webm'))html+=`<p class="danger">MP4 尚不可用，原始 WebM 已保留。转换中或重启后可重试。</p>${button('retry_export','重试转换',r.id)}`;
if(!job)html+=`<div class="task-controls">${button('generate','生成 SOP',r.id,'primary')}${button('later','稍后整理',r.id)}${button('keep','仅保留录像',r.id)}</div>`;
if(job&&!['running','queued','waiting_media'].includes(job.status))html+=`<div class="task-controls">${button('generate','新建分析任务',r.id)}</div>`;$('infoTitle').textContent='录像详情';$('infoBody').innerHTML=html;$('infoDialog').showModal();}
function markdown(text){const holder=document.createElement('div');let table=null,list=null;for(const line of text.split(/\r?\n/)){if(/^\s*\|/.test(line)){if(/^\s*\|?\s*[-:]+\s*\|/.test(line))continue;if(!table){const scroll=document.createElement('div');scroll.className='table-scroll';table=document.createElement('table');scroll.append(table);holder.append(scroll);}const tr=document.createElement('tr');line.replace(/^\s*\||\|\s*$/g,'').split(/(?<!\\)\|/).forEach(s=>{const td=document.createElement('td');td.textContent=s.trim().replace(/\\\|/g,'|');tr.append(td);});table.append(tr);continue;}table=null;if(!line.trim()){list=null;continue;}const match=line.match(/^(#{1,3})\s+(.*)$/);if(match){const h=document.createElement('h'+match[1].length);h.textContent=match[2];holder.append(h);}else if(/^\s*- /.test(line)){if(!list){list=document.createElement('ul');holder.append(list);}const li=document.createElement('li');li.textContent=line.replace(/^\s*- /,'');list.append(li);}else{list=null;const p=document.createElement('p');p.textContent=line;holder.append(p);}}return holder;}
function renderStepPreview(d){$('steps').innerHTML=(d.display_steps||[]).map((step,i)=>`<li data-step="${step.at}"><div class="step-head"><strong>${i+1}. ${escapeText(step.action)}</strong><button class="link timestamp" data-time="${step.at}">${String(Math.floor(step.at/60)).padStart(2,'0')}:${String(Math.floor(step.at%60)).padStart(2,'0')} ▷</button></div><p>${escapeText(step.expected)}</p><div class="meta">核验：${escapeText(step.verify)}</div><div class="meta">停止条件：${escapeText(step.stop)}</div></li>`).join('');$('markdown').replaceChildren(markdown(d.markdown));$('markdown').parentElement.open=!(d.display_steps?.length);}
async function review(args){detail=await request('detail',args);const d=detail,r=d.recording;current=r;$('listView').hidden=true;$('reviewView').hidden=false;const published=!!d.version||d.job?.status==='published';$('reviewTitle').textContent=r.title;$('reviewMeta').textContent=(r.operation_date||'日期未知')+' · '+(r.environment||'环境待确认');$('versionLabel').textContent=d.version?'v'+d.version.number:d.job?.status==='published'?'已发布':'草稿 · 待核对';$('reviewVideo').removeAttribute('src');if(d.url)$('reviewVideo').src=d.url;$('missingMedia').hidden=!!d.url;$('sourceDate').textContent=stamp(r.media.recorded_start_at);$('sourceInfo').innerHTML=`<div><dt>来源录像</dt><dd>${escapeText(r.media.name)}</dd></div><div><dt>作业日期</dt><dd>${escapeText(r.operation_date)}</dd></div><div><dt>更新时间</dt><dd>${escapeText(stamp(d.job?.updated_at||d.version?.reviewed_at))}</dd></div><div><dt>实机验证</dt><dd>尚未记录</dd></div>`;$('openSop').hidden=!d.version;$('versionHistory').hidden=!r.versions?.length;
$('goal').textContent='来源时间点为估计，请对照实际录像核查。';renderStepPreview(d);$('draftEditor').value=d.markdown;$('draftEditor').hidden=true;$('pending').hidden=published;$('editDraft').hidden=published;$('saveDraft').hidden=published;$('publish').hidden=published;$('publishedInfo').hidden=!published;$('publishedInfo').textContent=published?'人工核对已发布；实机验证须有独立作业证据。':'';$('reviewEnvironment').value=r.environment||'';$('questions').innerHTML=(d.data?.uncertainties||[]).map((q,i)=>`<label class="field">${escapeText(q)}<textarea data-answer="${i}" rows="2" placeholder="填写核对依据">${escapeText(d.resolutions?.[i]||'')}</textarea></label>`).join('');$('pendingTitle').textContent=(d.data?.uncertainties?.length||0)+' 项待确认';$('previousSection').hidden=!d.previous;$('diffText').textContent=d.diff||'';updatePublish();if(published)$('reviewHint').textContent='已发布版本保留来源与核对记录；后续变更请建立新版本。';await usageSummary();window.scrollTo({top:0});}
function updatePublish(){const complete=$('reviewEnvironment').value.trim()&&$('reviewer').value.trim()&&[...$('questions').querySelectorAll('textarea')].every(x=>x.value.trim());$('publish').disabled=!complete;$('reviewHint').textContent=complete?'请保存修改并核对通过，再发布为可用 SOP。':'补全适用环境、核对人和每项依据后可发布。';}
function reviewedVersion(){return detail?.version?.id||detail?.published_version;}
async function usageSummary(){const id=reviewedVersion();$('usageFeedback').hidden=!id;$('createRevision').hidden=!id;if(!id)return;const history=await request('feedback',{version_id:id});const successes=history.items.filter(x=>x.version_id===id&&x.kind==='success').length,open=history.items.filter(x=>x.status==='open').length;const summary=(successes?'本版本使用成功 '+successes+' 次（限已记录场景）':'本版本尚无成功使用记录')+(open?' · '+open+' 项反馈待处理':'');$('publishedInfo').textContent='人工核对已发布；'+summary+'。发布修订后仍需再次使用核验。';const cells=$('sourceInfo').querySelectorAll('dd');if(cells.length)cells[cells.length-1].textContent=summary;}
async function showFeedback(){const history=await request('feedback',{version_id:reviewedVersion()});$('feedbackTitle').textContent='使用反馈 · v'+history.version;$('feedbackDate').value=stamp(Date.now()).slice(0,10);$('feedbackEnvironment').value=current.environment||'';$('feedbackScenario').value='';$('feedbackNote').value='';$('feedbackLog').innerHTML=history.items.map(f=>`<p class="meta">${escapeText(f.run_date)} · v${f.source_number} · ${escapeText({issue:'遇到问题',suggestion:'改进建议',success:'本次成功'}[f.kind])}<br>${escapeText(f.environment)} · ${escapeText(f.scenario)}<br>${escapeText(f.note)}<br>${f.status==='open'?'待处理':f.status==='incorporated'?'已纳入 v'+f.incorporated_number+'，待使用核验':'当次结果已记录'}${f.resolution?'<br>修订说明：'+escapeText(f.resolution):''}</p>`).join('')||'<p class="meta">尚无使用反馈</p>';$('feedbackDialog').showModal();}
$('usageFeedback').onclick=()=>showFeedback().catch(e=>notify(e.message));
$('saveFeedback').onclick=async()=>{const b=$('saveFeedback');b.disabled=true;try{await request('add_feedback',{version_id:reviewedVersion(),kind:$('feedbackKind').value,date:$('feedbackDate').value,environment:$('feedbackEnvironment').value,scenario:$('feedbackScenario').value,note:$('feedbackNote').value});$('feedbackDialog').close();notify('使用反馈已保存；可从当前版本创建修订草稿');await refresh();await usageSummary();}catch(e){notify(e.message);}finally{b.disabled=false;}};
$('createRevision').onclick=async()=>{const b=$('createRevision');b.disabled=true;try{const job=await request('create_revision',{version_id:reviewedVersion()});await refresh();await review({job_id:job});$('draftEditor').hidden=false;notify('已打开修订草稿；按反馈修改、保存并核对后发布新版本');}catch(e){notify(e.message);}finally{b.disabled=false;}};
$('pending').addEventListener('input',updatePublish);$('editDraft').onclick=()=>{$('draftEditor').hidden=!$('draftEditor').hidden;};
async function saveDraft(){const resolutions={};$('questions').querySelectorAll('textarea').forEach(el=>resolutions[el.dataset.answer]=el.value);await request('save_draft',{job_id:detail.job.id,markdown:$('draftEditor').value,environment:$('reviewEnvironment').value,resolutions});detail=await request('detail',{job_id:detail.job.id});renderStepPreview(detail);$('reviewMeta').textContent=(detail.recording.operation_date||'日期未知')+' · '+detail.recording.environment;}
$('saveDraft').onclick=()=>saveDraft().then(()=>notify('草稿已保存')).catch(e=>notify(e.message));
$('publish').onclick=async()=>{const b=$('publish');b.disabled=true;try{await saveDraft();const id=await request('publish',{job_id:detail.job.id,reviewer:$('reviewer').value,reviewed:true});notify('SOP 已发布，对应 Codex skill 已启用');await refresh();await review({version_id:id});}catch(e){notify(e.message);updatePublish();}};
$('backList').onclick=()=>{$('reviewVideo').pause();$('reviewView').hidden=true;$('listView').hidden=false;refresh().catch(e=>notify(e.message));};
$('reviewVideo').ontimeupdate=()=>{const t=$('reviewVideo').currentTime;let active=null;document.querySelectorAll('[data-step]').forEach(x=>{x.classList.remove('active');if(Number(x.dataset.step)<=t)active=x;});if(active)active.classList.add('active');};
$('openOriginal').onclick=()=>request('open',{id:current.id,mode:'open'}).catch(e=>notify(e.message));$('openSop').onclick=()=>request('open_sop',{version_id:detail.version.id}).catch(e=>notify(e.message));
$('downloadSop').onclick=()=>{const blob=new Blob([detail.markdown],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sop.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('versionHistory').onclick=()=>{$('infoTitle').textContent='关联历史版本';$('infoBody').innerHTML=(current.versions||[]).map(v=>`<p>${button('version',v.title+' · v'+v.number+' · '+stamp(v.reviewed_at),v.id)}</p>`).join('');$('infoDialog').showModal();};
$('backup').onclick=()=>request('backup').then(name=>notify('台账备份已保存：'+name)).catch(e=>notify(e.message));
document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){$(close.dataset.close).close();if(close.dataset.close==='playerDialog'){$('player').pause();$('player').removeAttribute('src');}return;}const time=event.target.closest('[data-time]');if(time){const v=$('reviewVideo');if(v.src){v.currentTime=Number(time.dataset.time);v.play().catch(()=>{});}return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id,r=snapshot.recordings.find(x=>x.id===id);try{if(action==='document'){const d=await request('document',{id});$('infoTitle').textContent=d.title;$('infoBody').replaceChildren(markdown(d.markdown));$('infoBody').classList.add('doc');$('infoDialog').showModal();}else if(action==='play')play(r);else if(action==='generate'||action==='metadata'){if($('infoDialog').open)$('infoDialog').close();generate(r,action==='metadata');}else if(action==='info')info(r);else if(action==='review'){if(r.versions?.length&&r.job.status==='published')await review({version_id:r.versions[0].id});else await review({job_id:r.job.id});}else if(action==='version'){if($('infoDialog').open)$('infoDialog').close();await review({version_id:id});}else if(action==='open'||action==='reveal')await request('open',{id,mode:action});else if(action==='cancel'||action==='retry'){await request(action,{job_id:r.job.id});if($('infoDialog').open)$('infoDialog').close();await refresh();notify(action==='retry'?'已加入重试队列':'整理已取消，录像已保留');}else if(action==='later'||action==='keep'){await request('choice',{id,choice:action});$('infoDialog').close();await refresh();}else if(action==='retry_export'){notify(await request('retry_export',{id}));$('infoDialog').close();}else if(action==='withdraw'){if(confirm('停用这份 SOP 的 Codex skill？录像与历史版本保留。')){await request('withdraw',{sop_id:id,confirmed:true});await refresh();}}}catch(e){notify(e.message);}});
setInterval(()=>{if(ready&&!document.hidden)refresh().catch(()=>{});},5000);connect();
</script></body></html>'''
